DG='٠١٢٣٤٥٦٧٨٩'
def ar(x): return ''.join(DG[int(ch)] if ch.isdigit() else ('٫' if ch=='.' else ch) for ch in str(x))
def L(s): return f'<bdi dir="ltr">{s}</bdi>'
def nv(x): return f'−{ar(-x)}' if x<0 else ar(x)
def fr(f): f=F(f); return nv(f.numerator) if f.denominator==1 else f'{nv(f.numerator)}/{ar(f.denominator)}'
def rt(a,n): return L((ar(a) if a!=1 else '')+'√'+ar(n))
H='أَقْرَأُ السُّؤَالَ، ثُمَّ أُظَلِّلُ حَرْفَ الإِجَابَةِ الصَّحِيحَةِ فِي وَرَقَةِ الإِجَابَةِ'
def W(t,rows): return {"type":"words","title":t,"hint":H,"rows":rows}
def mk(rows):
  out=[]
  for q,c,ds,p in rows:
    o=list(ds); o.insert(p,c); assert len(set(o))==len(o),o; out.append([q,o])
  return out
def simp(n):
  a=1
  for k in range(2,int(n**.5)+1):
    while n%(k*k)==0: n//=k*k; a*=k
  return a,n
